import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageOps

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_FILE = Path("/app/workspace/stat_ocr.xlsx")

PRIORITY_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED",
]

STOP_RE = re.compile(r"GST\s*SUMMARY", re.IGNORECASE)
INCL_GST_RE = re.compile(r"INCL(USIVE|UDING|\.)?\s*(OF\s*)?GST")
EXCL_GST_RE = re.compile(r"EXCL(UDING|UDED|USIVE|\.)?\s*(OF\s*)?GST")
AMOUNT_RE = re.compile(r"(?<![\d.\-])(\d{1,3}(?:,\d{3})*\.\d{2})(?!\d)")

MONTH_MAP = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DATE_PATTERNS = [
    (re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})\b"), "dmy4"),
    (re.compile(r"\b(\d{1,2})[/\-](\d{1,2})[/\-](\d{2})\b"), "dmy2"),
    (re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,})\s+(\d{2,4})\b"), "dMy"),
]


def normalize_text(text):
    text = re.sub(r"(\d)\.\s+(\d{2})(?!\d)", r"\1.\2", text)
    text = re.sub(r"(\d),\s*(\d{2})(?!\d)", r"\1.\2", text)
    return text


def is_excluded(line_upper):
    cleaned = INCL_GST_RE.sub("", line_upper)
    cleaned = EXCL_GST_RE.sub("", cleaned)
    return any(k in cleaned for k in EXCLUSION_KEYWORDS)


def is_simple_kw_line(line_upper, keyword):
    without_kw = line_upper.replace(keyword, " ", 1)
    rest = re.sub(r"[\W_\d]+", "", without_kw)
    return len(rest) <= 2


def extract_total_with_priority(text):
    lines = text.splitlines()
    uppers = [l.upper() for l in lines]
    stop_idx = len(lines)
    for i, u in enumerate(uppers):
        if STOP_RE.search(u):
            stop_idx = i
            break

    for prio_idx, keywords in enumerate(PRIORITY_KEYWORDS, 1):
        matches = []
        for i in range(stop_idx):
            upper = uppers[i]
            if is_excluded(upper):
                continue
            matched_kw = next((k for k in keywords if k in upper), None)
            if matched_kw is None:
                continue
            amts = AMOUNT_RE.findall(lines[i])
            if len(amts) >= 2:
                continue
            if len(amts) == 1:
                matches.append(amts[0].replace(",", ""))
            elif is_simple_kw_line(upper, matched_kw) and i + 1 < stop_idx:
                next_amts = AMOUNT_RE.findall(lines[i + 1])
                if len(next_amts) == 1 and not is_excluded(uppers[i + 1]):
                    matches.append(next_amts[-1].replace(",", ""))
        if matches:
            return matches[-1], prio_idx
    return None, 99


def _normalize_year(year):
    if year < 100:
        return 2000 + year if year < 70 else 1900 + year
    if year > 2050:
        fixed = int(str(year).replace("7", "1"))
        if 2000 <= fixed <= 2030:
            return fixed
    return year


def _try_date(d, m, y):
    y = _normalize_year(y)
    try:
        return datetime(y, m, d).strftime("%Y-%m-%d")
    except ValueError:
        return None


def extract_date(text):
    for pattern, kind in DATE_PATTERNS:
        for match in pattern.finditer(text):
            if kind in ("dmy4", "dmy2"):
                d, m, y = (int(x) for x in match.groups())
                result = _try_date(d, m, y)
                if result:
                    return result
            elif kind == "dMy":
                d_str, mon_str, y_str = match.groups()
                mon = MONTH_MAP.get(mon_str[:3].upper())
                if mon is None:
                    continue
                result = _try_date(int(d_str), mon, int(y_str))
                if result:
                    return result
    return None


def ocr_variants(path):
    img = Image.open(path)
    yield pytesseract.image_to_string(img)

    gray = ImageOps.grayscale(img)
    enhanced = ImageOps.autocontrast(gray)
    upscaled = enhanced.resize((enhanced.width * 2, enhanced.height * 2), Image.LANCZOS)
    yield pytesseract.image_to_string(upscaled, config="--psm 6")
    yield pytesseract.image_to_string(upscaled, config="--psm 4")


def process_image(path):
    results = []
    for text in ocr_variants(path):
        text = normalize_text(text)
        date = extract_date(text)
        total, priority = extract_total_with_priority(text)
        results.append((date, total, priority))

    chosen_date = None
    date_counts = Counter(d for d, _, _ in results if d is not None)
    if date_counts:
        chosen_date = date_counts.most_common(1)[0][0]

    chosen_total = None
    best_priority = 99
    totals_by_priority = {}
    for _, t, p in results:
        if t is None:
            continue
        totals_by_priority.setdefault(p, []).append(t)
        if p < best_priority:
            best_priority = p
    if best_priority < 99:
        candidates = totals_by_priority[best_priority]
        counts = Counter(candidates)
        chosen_total = counts.most_common(1)[0][0]

    return chosen_date, chosen_total


def main():
    rows = []
    for path in sorted(IMG_DIR.iterdir()):
        if path.suffix.lower() not in {".jpg", ".jpeg", ".png"}:
            continue
        date, total = process_image(path)
        rows.append((path.name, date, total))
        print(f"{path.name}: date={date}, total={total}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for row in rows:
        ws.append(row)
    wb.save(OUT_FILE)
    print(f"Saved {len(rows)} rows to {OUT_FILE}")


if __name__ == "__main__":
    main()
